import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"ADR 0005 — Typed decisions through a cascade; Laya as the embedded decision model","description":"","frontmatter":{},"headers":[],"relativePath":"reference/adr/0005-typed-decisions.md","filePath":"reference/adr/0005-typed-decisions.md"}`),a={name:`reference/adr/0005-typed-decisions.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0005-—-typed-decisions-through-a-cascade-laya-as-the-embedded-decision-model" tabindex="-1">ADR 0005 — Typed decisions through a cascade; Laya as the embedded decision model <a class="header-anchor" href="#adr-0005-—-typed-decisions-through-a-cascade-laya-as-the-embedded-decision-model" aria-label="Permalink to “ADR 0005 — Typed decisions through a cascade; Laya as the embedded decision model”">​</a></h1><ul><li><strong>Status:</strong> Accepted</li><li><strong>Date:</strong> 2026-10-13</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Routing used a cheap generative model (a one-word classification); readers used hand-written rules; some safety checks were prompt rules. A hosted &quot;decision model&quot; API (Jev, TypeSafe AI) showed the shape that fits: typed questions answered with calibrated probabilities in one forward pass. It is proprietary and metered per token. Laya (Convai Innovations, Apache-2.0) is an open-weight model that speaks the same System One protocol, with published parity on the typed-decisions benchmark.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li>A typed-decision interface (<code>choice</code>, <code>noul</code>, <code>score</code> → distributions) with pluggable backends and a cascade: rules → System One server (Laya via Ollama/laya-serve, or Jev) → LLM with logprobs. The agent never knows which link answered; <code>answered_by</code> is on the result.</li><li>Laya is the embedded open-source decision model: a compose profile pulls it; the CLI, the MCP server and the runtime&#39;s router use it when <code>VERDICT_SYSTEMONE_URL</code> is set.</li><li>The kit also SERVES the protocol (<code>createSystemOneServer</code>) so a rules + LLM cascade can stand in for a decision model behind the same URL.</li><li>Confidence is derived uniformly (distribution concentration; |2p−1|) so links compare; calibration (temperature, ECE, abstention threshold) is measured on the operator&#39;s own data.</li><li>The create gate stays rules-only; a decision model may advise a reader on the model-handoff path, never loosen a gate where a false yes performs a write.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>Routing costs nothing with keywords, ~30 ms with Laya, one short model call only as a last resort. The vendor dependency is optional and replaceable by anything that speaks the protocol.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/adr/0005-typed-decisions.md">docs/adr/0005-typed-decisions.md</a> — edit it there; the site mirrors the repository.</small></p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};